package com.inovagab.inovagab.dto; import jakarta.validation.constraints.*; import java.time.LocalDate; public class ProjetoRequest { @NotBlank private String nome,descricao,estrategiaId; @PositiveOrZero private double investimento; @NotNull private LocalDate prazo; private String status="PLANEJADO"; public String getNome(){return nome;} public void setNome(String v){nome=v;} public String getDescricao(){return descricao;} public void setDescricao(String v){descricao=v;} public String getEstrategiaId(){return estrategiaId;} public void setEstrategiaId(String v){estrategiaId=v;} public double getInvestimento(){return investimento;} public void setInvestimento(double v){investimento=v;} public LocalDate getPrazo(){return prazo;} public void setPrazo(LocalDate v){prazo=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
